const f = (key, label, value, unit = '', type = 'number', extra = {}) => ({ key, label, value, type, ...(unit ? { unit } : {}), ...extra });
const n = (v, key, { min = -Infinity, max = Infinity, positive = false } = {}) => {
  const raw = v?.[key];
  if (raw === undefined || raw === null || (typeof raw === 'string' && raw.trim() === '')) throw new Error(`${key} is required.`);
  const x = Number(raw);
  if (!Number.isFinite(x)) throw new Error(`${key} must be a finite number.`);
  if (Math.abs(x) > 1e12) throw new Error(`${key} is outside the safe calculation range.`);
  if (positive && x <= 0) throw new Error(`${key} must be greater than zero.`);
  if (x < min || x > max) throw new Error(`${key} must be between ${min} and ${max}.`);
  return x;
};
const txt = (v, key) => { const x = String(v?.[key] ?? '').trim(); if (!x) throw new Error(`${key} is required.`); return x; };
const date = (v, key) => { const s = txt(v, key); if (!/^\d{4}-\d\d-\d\d$/.test(s)) throw new Error(`${key} must be a valid date.`); const d = new Date(`${s}T00:00:00Z`); if (Number.isNaN(+d) || d.toISOString().slice(0,10) !== s) throw new Error(`${key} must be a valid date.`); return d; };
const result = (value, unit, label, details = [], note) => ({ value, unit, label, details, ...(note ? { note } : {}) });
const basicInfo = {
'age-calculator':['Find a person’s completed age between two calendar dates. Calendar anniversaries are compared in UTC, so daylight-saving changes cannot add or remove a day. The result also reports elapsed days and the next birthday; a February 29 birthday is observed on March 1 in non-leap years.','For a birth date of 2000-05-10 and a date of 2025-05-09, the completed age is 24; one day later it becomes 25.',['Why can the birthday fall on March 1?','This calculator uses March 1 when the year has no February 29. Local legal conventions can differ.'],['Does age include the birth day?','Completed years count anniversaries reached, not inclusive day counts.']],
'date-calculator':['Add or subtract a signed number of calendar days from a chosen date. Calendar arithmetic is performed at midnight UTC and keeps the intended year-month-day even across daylight-saving transitions.','Adding 30 days to 2024-01-15 gives 2024-02-14.',['Are dates counted inclusively?','No. Adding one day to a date returns the following calendar date.'],['What happens with negative days?','A negative offset moves backward by that many calendar days.']],
'time-calculator':['Add or subtract clock durations using hours, minutes, and seconds. The output wraps across midnight and separately reports how many whole days the arithmetic crossed. Enter durations as elapsed time, not as local timestamps.','23:30 plus 2 hours 45 minutes is 02:15 the next day.',['Can hours exceed 24?','Yes. Hours are elapsed duration and may exceed a day.'],['Does this account for time zones?','No. It is clock arithmetic; use the time-zone calculator for location conversions.']],
'hours-calculator':['Convert a decimal hour total into hours and minutes, or convert hours and minutes back to decimal hours. The decimal result is useful for payroll and timesheets, while the split form avoids treating minutes as hundredths of an hour.','7 hours 30 minutes equals 7.5 decimal hours.',['Are minutes base 100?','No. One hour has 60 minutes, so 30 minutes contributes 0.5 hours.'],['Can I enter negative hours?','Yes, signed values represent corrections or balances.']],
'gpa-calculator':['Compute a weighted grade-point average from course grades and credit weights. Enter one grade point per course and its credit value; total quality points are divided by total credits. This calculator does not assume a country’s grading scale, so translate grades to your institution’s scale first.','A 3-credit course at 4.0 and a 1-credit course at 3.0 produce (12+3)/4 = 3.75.',['Does GPA use course credits?','Yes, credits weight each course; equal weighting is appropriate only when course credits are equal.'],['Can I enter percentages directly?','Only if your institution defines those numbers as grade points. Convert letter or percentage grades first.']],
'grade-calculator':['Calculate a course average from scores and their percentage weights, then estimate the score needed on a remaining assessment to reach a target. Weights should sum to 100% across completed and remaining work; if they do not, the weighted average is normalized over entered completed work.','Scores 85% at 40% weight and 90% at 60% weight yield an 88% course grade.',['Can the required final score exceed 100%?','Yes; that means the target is mathematically unreachable under the entered weights.'],['Should weights total 100?','They should for a full course plan; the displayed current average normalizes completed weights.']],
'height-calculator':['Convert height between centimeters, meters, feet, and inches without mixing decimal feet with feet-and-inches notation. The equivalent is calculated from exact unit ratios and rounded only for display.','170 cm is about 5 ft 6.93 in, or 1.70 m.',['How many centimeters are in an inch?','Exactly 2.54 cm.'],['Is decimal feet the same as feet and inches?','No. 5.5 decimal feet equals 5 ft 6 in.']],
'concrete-calculator':['Estimate concrete volume for a rectangular slab using length, width, and thickness. The output includes cubic meters, cubic yards, and an optional overage allowance; it does not account for irregular edges, subgrade losses, or reinforcement displacement.','A 4 m by 3 m slab at 0.10 m thick needs 1.2 m³ before any waste allowance.',['How much extra should I order?','Use an allowance suited to the shape, access, and placement conditions; the default is only an editable planning assumption.'],['Does this convert volume to bags?','No. Bag yield varies by product; use the manufacturer’s stated yield.']],
'ip-subnet-calculator':['Inspect an IPv4 address and CIDR prefix to determine its network, broadcast address, mask, and usable host range. This is arithmetic for conventional IPv4 subnets; /31 and /32 have special point-to-point and host semantics, which are identified in the result.','192.168.1.10/24 belongs to 192.168.1.0/24, whose broadcast is 192.168.1.255.',['Does it support IPv6?','No, this tool validates dotted-decimal IPv4 only.'],['Why are /31 and /32 different?','They are commonly used for point-to-point links or a single address, so ordinary network/broadcast host exclusions do not apply.']],
'bra-size-calculator':['Estimate a US/UK-style band and cup size from underbust and bust measurements in inches. The result is a starting point because sizing systems, brands, fit preferences, and measurement technique differ; sister sizes can feel different across styles.','A 34-inch underbust and 37-inch bust suggests roughly 34C under this simple inch-difference rule.',['Is the result a guaranteed fit?','No. It is a measurement-based estimate; try the brand’s chart and assess band, cup, and wire comfort.'],['Which sizing system is used?','The output follows the common US/UK band-plus-inch-difference convention and does not convert to EU labels.']],
'password-generator':['Generate a password from user-selected length and character groups using a cryptographically secure random source. Each enabled group is guaranteed to appear at least once, and rejection sampling avoids modulo bias. Keep generated secrets private and store them in a password manager.','A 20-character password using all four groups has a much larger search space than a short dictionary word.',['Is generation secure offline?','It uses the browser or runtime cryptographic random generator; the module does not transmit the output.'],['Can I omit confusing characters?','Yes. Excluding look-alike characters is useful for manual transcription but slightly reduces the available alphabet.']],
'dice-roller':['Simulate one or more fair dice with a chosen number of sides and report each roll plus the total. Secure runtime randomness is used when available; every face from 1 through the selected side count has equal probability.','Rolling two six-sided dice can produce totals from 2 through 12.',['Are rolls predictable?','The calculator uses the platform’s secure random API when available, but it is for casual play rather than audited gambling.'],['Can I use nonstandard dice?','Yes. Choose any integer side count within the field limits.']],
'conversion-calculator':['Convert between common length, mass, volume, temperature, area, speed, and energy units with explicit source and destination units. Conversions use fixed ratios or the standard affine temperature equations, so temperature offsets are not treated as simple multipliers.','10 miles is 16.09344 kilometers; 32°F is 0°C.',['Why can temperature conversions have an offset?','Celsius and Fahrenheit have different zero points, so their conversion includes both a scale and an offset.'],['Are fluid ounces and ounces interchangeable?','No. One measures volume and the other mass; select units within the same dimension.']],
'fuel-cost-calculator':['Estimate trip fuel expense from distance, fuel economy, and the price per fuel unit. Choose metric consumption (L/100 km) or distance-per-volume (mpg or km/L); the calculator converts the required fuel amount before multiplying by price.','For 500 km at 8 L/100 km and €1.80 per liter, fuel costs about €72.',['Does this include tolls?','No. It estimates fuel only; add tolls, parking, and vehicle wear separately.'],['Which mpg definition is used?','The field specifies US or Imperial mpg, since the two gallons have different volumes.']],
'voltage-drop-calculator':['Estimate DC two-conductor cable voltage drop using conductor resistivity, length, and current. The round-trip length is twice the one-way run, and resistance scales with conductor area; this simplified model excludes connector resistance, temperature rise, AC reactance, and installation-code limits.','A 10 m one-way copper run carrying 5 A through 1.5 mm² wire has about 1.17 V drop at 20°C.',['Does the result certify wire size?','No. Check applicable electrical codes, ampacity, insulation, installation method, and temperature.'],['Why is cable length doubled?','Current travels out and back in a two-wire DC circuit.']],
'btu-calculator':['Estimate heating or cooling capacity in BTU per hour from room area and an adjustable load factor. The result is a screening estimate only; insulation, windows, ceiling height, climate, occupancy, and equipment efficiency can change a real load calculation substantially.','A 400 ft² room at 25 BTU/h per ft² estimates 10,000 BTU/h.',['Is area alone enough for HVAC sizing?','No. A Manual J or equivalent building-load assessment uses construction, climate, windows, and other inputs.'],['What is a BTU?','A British thermal unit is a unit of heat energy; BTU/h expresses a rate of heat transfer.']],
'square-footage-calculator':['Find floor or surface area from length and width, with a choice of feet or meters and an optional count of identical rectangles. The calculator reports square feet and square meters; split complex spaces into rectangles and add their areas.','A 12 ft by 15 ft room has 180 square feet.',['Should closets be included?','Include each surface you plan to cover, then subtract openings only when their area is material.'],['Does this include waste?','No. Add a separate material allowance after measuring the net area.']],
'time-card-calculator':['Calculate elapsed paid time from clock-in and clock-out times, including an unpaid break and an overnight shift. Enter times in 24-hour format; if clock-out is earlier than clock-in, the shift is treated as ending the next day.','08:30 to 17:00 with a 30-minute unpaid break is 8 paid hours.',['Are overtime rules included?','No. This gives elapsed hours; apply local overtime, rounding, and break rules separately.'],['Can a shift cross midnight?','Yes. An earlier end time is interpreted as the following day.']],
'time-zone-calculator':['Convert a local date and time between two named IANA time zones using their daylight-saving rules for that date. Results retain the destination’s local clock and UTC offset, and flag invalid zones or nonexistent local times rather than silently guessing.','09:00 in New York can map to different UTC offsets depending on the date because daylight saving changes.',['Why does the same conversion change by season?','Many regions change UTC offset seasonally; the selected date determines the applicable offset.'],['Which time-zone names work?','Use IANA identifiers such as Europe/Berlin or America/New_York.']],
'love-calculator':['Create a playful compatibility score from two names using a repeatable character-code calculation. It is entertainment only: names cannot measure relationship quality, consent, communication, or compatibility. Use the result as a lighthearted conversation starter, not advice.','Entering the same two names in either order produces the same score.',['Is the score scientifically validated?','No. It is a deterministic novelty result with no relationship science behind it.'],['Why does order not matter?','The calculator normalizes the two names before hashing so the same pair gets a repeatable score.']],
'gdp-calculator':['Estimate gross domestic product with the expenditure identity: household consumption plus investment plus government purchases plus exports minus imports. Enter values in one consistent currency and time period; this computes a nominal total and does not adjust for inflation or population.','C=500, I=120, G=200, X=80, M=100 gives GDP of 800 in the chosen units.',['Why are imports subtracted?','Imported goods may appear in consumption or investment but were not produced domestically.'],['Is this real GDP?','No. Real GDP requires price-index adjustment across periods.']],
'gas-mileage-calculator':['Calculate fuel economy from distance traveled and fuel consumed, showing both miles per US gallon and liters per 100 kilometers where applicable. Distance and fuel must be measured over the same fill-to-fill interval for a meaningful result.','Driving 300 miles while using 10 US gallons is 30 mpg.',['Is a higher L/100 km better?','No. Lower L/100 km means less fuel used for each 100 kilometers.'],['Why use full tanks?','Consistent fill-to-fill measurements reduce errors from fuel gauge estimation.']],
'horsepower-calculator':['Estimate mechanical horsepower from torque and rotational speed using HP = torque × RPM / 5252 when torque is in lb-ft. The result is shaft power under that conventional unit system; drivetrain losses and measurement accuracy are not included.','300 lb-ft at 4,000 rpm corresponds to about 228 horsepower.',['Can horsepower be estimated from torque alone?','No. Power also depends on rotational speed.'],['Is this wheel horsepower?','Only if the torque input was measured at the wheels; the equation itself does not estimate drivetrain loss.']],
'engine-horsepower-calculator':['Estimate engine power from torque and engine speed, with explicit choices for lb-ft or newton-meters and horsepower or kilowatts. Torque and RPM must refer to the same operating point; peak torque and peak RPM from different points cannot be combined into peak power.','A torque reading of 300 lb-ft at 4,000 rpm is about 228 hp.',['Why can peak horsepower occur above peak torque RPM?','Power is torque multiplied by rotational speed, so falling torque can be offset by rising RPM.'],['Does this include drivetrain loss?','No. It estimates power at the shaft represented by the torque measurement.']],
'stair-calculator':['Lay out a straight staircase from floor-to-floor rise and available horizontal run. It computes integer risers, actual riser height, approximate tread depth, and pitch; verify headroom, landing, handrail, and local building-code rules before building.','A 108-inch rise divided into 15 risers gives 7.2-inch risers.',['Does this guarantee code compliance?','No. Stair geometry, landings, headroom, guards, and permitted tolerances vary by jurisdiction.'],['Why round to a whole riser count?','A stair needs a whole number of equal risers; the calculator recalculates their actual height.']],
'resistor-calculator':['Decode a four-band resistor color code into nominal resistance and tolerance, or calculate a series resistor for an LED from supply voltage, LED forward voltage, and target current. The current-limiting calculation is idealized; choose a standard value and check resistor power dissipation.','Red-violet-brown-gold represents 270 Ω ±5%.',['Can a color code tell the exact measured value?','No. It gives nominal resistance and tolerance; actual resistance can vary within that range.'],['Why check resistor wattage?','The resistor dissipates electrical power as heat and must be rated for the load with suitable margin.']],
'ohms-law-calculator':['Solve one unknown in Ohm’s law using any two of voltage, current, and resistance, then report power. Inputs must describe the same circuit condition; the equations model ideal lumped electrical behavior and do not cover nonlinear components or transient effects.','12 V across 6 Ω gives 2 A and 24 W.',['What if I enter all three values?','The calculator checks consistency and reports a mismatch rather than choosing one value arbitrarily.'],['Does Ohm’s law apply to every component?','Only to components behaving ohmically over the relevant operating range.']],
'electricity-calculator':['Estimate electrical energy and cost from power, hours of use, and an adjustable price per kilowatt-hour. For variable loads, use average power over the measured interval; fixed charges, taxes, demand fees, and time-of-use rates are not included.','A 100 W lamp used 5 hours consumes 0.5 kWh.',['How do watts become kilowatt-hours?','Multiply kW by hours; 1,000 watts used for one hour is 1 kWh.'],['Does the estimate match a utility bill?','It covers usage energy only; billing structures add other charges.']],
'shoe-size-conversion':['Convert a shoe size between selected US men’s, US women’s, UK, and EU scales using a practical chart-based approximation. Manufacturers vary in last shape and labeling, so use the brand’s own chart and foot length for a purchase decision.','A US men’s size 9 is commonly near UK 8 and EU 42, with brand variation.',['Are size scales exact?','No. The mappings are approximate and brand-specific fits vary.'],['Should I measure foot length?','Yes. Measure both feet while standing and compare with the manufacturer’s sizing guide.']],
'tip-calculator':['Calculate a restaurant tip from the bill and tip percentage, then split the total among diners. You can choose whether the percentage applies before or after tax; the per-person result is rounded for currency display, so the final person may need to absorb a cent difference.','A 20% tip on $80 is $16; four people pay $24 each including tip.',['Should I tip on tax?','Practices differ; select the basis that matches your local custom.'],['Why may split amounts differ by a cent?','Currency rounding can leave a remainder when the total does not divide evenly.']],
'mileage-calculator':['Compute distance between two odometer readings, optionally subtracting a correction or comparing multiple trips. Enter values in the same distance unit; this tool does not infer a route or account for GPS/odometer calibration.','Odometer readings of 12,340 and 12,615 miles show 275 miles traveled.',['What if the odometer rolled over?','Enter the rollover modulus or calculate the segments separately; a negative result is rejected.'],['Does it map a route?','No. It calculates from the values you provide.']],
'density-calculator':['Calculate density as mass divided by volume and show the equivalent in common SI units. Mass and volume must describe the same sample at the same conditions; porous materials, mixtures, and temperature-sensitive fluids may need a more specific measurement method.','A 500 g object occupying 200 cm³ has density 2.5 g/cm³.',['How is density different from weight?','Density is mass per volume; weight is gravitational force.'],['Can volume be zero?','No. A positive volume is required to define density.']],
'mass-calculator':['Find mass from density and volume using m = ρV, with matching unit choices and equivalent outputs in grams and kilograms. The estimate assumes density is uniform throughout the object and that the chosen density matches its material and conditions.','A 2 L volume of water at about 1 kg/L has a mass near 2 kg.',['Does mass change with location?','Mass is intrinsic; apparent weight changes with gravity.'],['What if an object has mixed materials?','Calculate each part separately and add the masses, or use a measured average density.']],
'weight-calculator':['Convert mass to gravitational force using W = m × g, with an editable gravitational acceleration. The default is standard Earth gravity; this is a force estimate and should not be confused with everyday scale readings that often display mass units.','A 10 kg mass weighs about 98.1 newtons at standard gravity.',['Why does weight use newtons?','Weight is a force, and the SI unit of force is the newton.'],['Can I use this on another planet?','Yes. Enter an appropriate local gravitational acceleration, if known.']],
'speed-calculator':['Calculate average speed from distance and elapsed time and convert between common speed units. Average speed uses total distance divided by total duration; it differs from average velocity when direction and displacement matter.','A 150 km trip taking 2 hours averages 75 km/h.',['Does it include stops?','Include all elapsed time for trip-average speed or exclude stops for moving speed.'],['Can speed be negative?','Speed is a nonnegative magnitude; direction belongs to velocity.']],
'molarity-calculator':['Calculate solution molarity from solute amount and final solution volume, or determine the mass required when molecular weight is known. Volume must be final solution volume in liters, not simply solvent volume before dissolving.','0.5 mol in a final volume of 2 L is 0.25 mol/L.',['What does M mean?','One molar (1 M) means one mole of solute per liter of solution.'],['Can this replace lab preparation guidance?','No. Account for purity, temperature, hazards, and validated lab procedures.']],
'molecular-weight-calculator':['Estimate molar mass by parsing a chemical formula and summing standard atomic weights for each element and subscript. Parentheses and nested groups are supported; charges, isotope notation, hydrates, and ambiguous informal names should be entered as explicit formulas or handled by a chemistry reference.','H2O is approximately 18.015 g/mol.',['Does it accept names like water?','No. Enter a chemical formula such as H2O.'],['Are atomic weights exact?','They are standard conventional values; isotope composition can change a real sample’s molar mass.']],
'roman-numeral-converter':['Convert positive integers to standard Roman numerals or validate and parse a canonical Roman numeral. The supported range is 1 through 3,999, using subtractive forms such as IV and CM; historical variants and zero are not represented.','2024 converts to MMXXIV.',['Can it represent zero?','No standard Roman numeral for zero is included in this conventional system.'],['Why reject some letter strings?','The parser requires canonical subtractive notation and rejects malformed or nonstandard sequences.']],
'golf-handicap-calculator':['Estimate a World Handicap System index from 3 to 20 entered score differentials. It selects the lowest differentials, applies the published adjustment for 3, 4, and 6 scores, then rounds to one decimal place. The calculation assumes you already have valid differentials and omits soft caps, exceptional-score adjustments, and committee review, so it is not an official handicap record.','With 20 differentials, the index is the average of the lowest 8, rounded to one decimal place.',['Is this an official handicap?','No. An authorized golf association uses a fuller ruleset, score posting, and safeguards.'],['How is a score differential formed?','It depends on adjusted gross score, course rating, slope rating, and applicable playing conditions.']],
'sleep-calculator':['Plan wake-up or bedtime windows around approximate 90-minute sleep cycles and a configurable time to fall asleep. Sleep cycles vary between people and across the night; the suggestions are planning estimates, not a diagnosis or a promise to wake refreshed.','If you need to wake at 07:00 and take 15 minutes to fall asleep, six cycles suggest bedtime near 21:45.',['Are sleep cycles exactly 90 minutes?','No. Cycle duration varies, so treat the times as rough planning anchors.'],['How much sleep should I target?','Needs vary by age and health; follow reputable clinical guidance rather than optimizing only for cycle count.']],
'tire-size-calculator':['Estimate tire sidewall height, overall diameter, circumference, and speedometer difference from a metric tire code such as 205/55R16. It assumes the nominal width and aspect ratio; actual dimensions vary by model, rim width, pressure, wear, and load.','A 205/55R16 tire has a nominal sidewall height of 112.75 mm.',['Does it verify wheel fitment?','No. Check manufacturer fitment, clearance, load index, and speed rating.'],['Why can the real diameter differ?','The code gives nominal dimensions; casing design and operating conditions affect measured size.']],
'roofing-calculator':['Estimate roof covering area from the building footprint, roof pitch, and waste allowance. The pitch multiplier converts horizontal plan area to sloped surface area; valleys, dormers, overhangs, and complex geometry may require a measured takeoff.','A 1,000 ft² footprint at a 6:12 pitch has about 1,118 ft² of sloped area before waste.',['What does 6:12 pitch mean?','The roof rises 6 inches for every 12 inches of horizontal run.'],['How much waste should I add?','It depends on roof complexity, material, and installation pattern; use a contractor’s takeoff for ordering.']],
'tile-calculator':['Estimate tile count from floor area and individual tile dimensions, with an adjustable cutting and breakage allowance. The calculation rounds up to whole tiles and excludes grout spacing, pattern cuts, spare stock, and carton pack sizes unless you account for them in the allowance.','A 100 ft² floor covered by 1 ft² tiles with 10% extra requires 110 tiles.',['Should I order extra tiles?','Yes, a suitable reserve helps cover cuts, breakage, and future repairs.'],['Does it calculate cartons?','No. Divide the rounded tile count by the package yield and round up separately.']],
'mulch-calculator':['Estimate mulch volume from bed area and target depth, then convert cubic feet to cubic yards. Measure each bed and add its area; settling, uneven ground, and the product’s moisture content affect the delivered depth.','A 200 ft² bed at 3 inches deep needs about 1.85 cubic yards.',['Is three inches always right?','Depth depends on plant type and existing mulch; avoid piling mulch against trunks.'],['Why purchase cubic yards?','Bulk landscape materials are commonly sold by volume in cubic yards.']],
'gravel-calculator':['Estimate gravel volume from area and compacted depth, with an editable material density to convert volume to mass. Aggregate density varies with grading, moisture, and compaction, so use supplier data for a reliable tonnage order.','A 500 ft² driveway layer 4 inches deep is about 6.17 cubic yards before compaction allowance.',['Does it account for compaction?','Use an adjusted depth or allowance; actual compaction depends on material and equipment.'],['Why can weight vary for the same volume?','Stone size distribution, void space, moisture, and source affect bulk density.']],
'wind-chill-calculator':['Estimate the US National Weather Service wind-chill temperature from air temperature in Fahrenheit and wind speed in miles per hour. The index applies only at or below 50°F with wind above 3 mph and assumes shade; sun exposure can change how conditions feel.','At 30°F with 10 mph wind, the standard equation gives a wind chill near 21°F.',['Does wind chill cool objects below air temperature?','It describes heat loss from exposed skin; it does not make an object colder than the air temperature.'],['When is the formula valid?','The NWS formulation is intended for air temperatures at or below 50°F and wind speeds above 3 mph.']],
'heat-index-calculator':['Estimate apparent heat using the National Weather Service Rothfusz regression for warm, humid conditions, with its low-humidity and high-humidity adjustments. It is intended for shaded conditions and can be misleading outside its calibrated range; direct sun and exertion increase heat stress.','At 90°F and 70% relative humidity, the index is approximately 106°F.',['Does the result include direct sunlight?','No. The standard index assumes shade; sun can raise apparent heat and risk.'],['Is the equation valid at all temperatures?','No. NWS guidance uses a simpler approach below about 80°F and warns about extreme conditions.']],
'dew-point-calculator':['Estimate dew point from air temperature and relative humidity with the Magnus approximation. The result represents the temperature at which air becomes saturated under the model; indoor surfaces, pressure, and measurement error can affect condensation in practice.','At 20°C and 50% RH, dew point is about 9.3°C.',['What does dew point tell me?','It is a practical indicator of moisture content and condensation potential.'],['Is it exact?','No. It uses an approximation and depends on accurate temperature and humidity readings.']],
'bandwidth-calculator':['Estimate transfer time or required data rate from file size and network speed, with decimal or binary byte units and an efficiency allowance. The ideal rate ignores latency, congestion, protocol overhead, server limits, and competing traffic; real transfers often take longer.','A 1 GB decimal file over 100 Mbps takes about 80 seconds at full theoretical speed.',['Why is there an efficiency setting?','Real links spend capacity on protocol overhead and other traffic.'],['Are Mbps and MB/s the same?','No. One byte contains eight bits, so 80 Mbps equals 10 MB/s before overhead.']],
'base64-encode-decode':['Encode UTF-8 text as Base64 or decode Base64 back into text, validating malformed input instead of silently accepting corrupted data. Base64 is a text representation, not encryption; anyone who obtains the encoded string can decode it.','The text “cat” encodes to “Y2F0”.',['Does Base64 protect a secret?','No. It is reversible encoding, not encryption or access control.'],['Does it support arbitrary binary files?','This text utility handles UTF-8 strings; binary files need byte-oriented tooling.']],
'url-encode-decode':['Percent-encode or decode URL components as UTF-8 text. Component encoding treats spaces as %20 and preserves only unreserved characters; full URL structures should be assembled from separately encoded path and query components.','“red tea & milk” becomes “red%20tea%20%26%20milk” as a component.',['Should I encode an entire URL?','Usually encode individual values, not separators such as /, ?, and & that define URL structure.'],['Is encoding security?','No. It ensures safe representation in a URL; it does not sanitize every application context.']],
'time-duration-calculator':['Find elapsed duration between two clock times, optionally spanning midnight, and return the total in hours and minutes. If end time is earlier than start, the calculator interprets it as the next day; use the date calculator for durations across multiple dates.','22:45 to 01:15 is 2 hours 30 minutes when crossing midnight.',['Does it include seconds?','This version accepts hours and minutes; seconds are not modeled.'],['Can I force same-day negative duration?','No. Earlier end times are treated as overnight intervals.']],
'day-counter':['Count whole calendar-day boundaries between two dates and optionally use inclusive counting. Dates are compared in UTC so daylight-saving transitions do not change the day count. Reverse endpoints are accepted and reported as an absolute difference.','From March 1 to March 8 is 7 elapsed days, or 8 dates when counted inclusively.',['Why is inclusive count one larger?','It counts both endpoint dates; elapsed days count the boundaries crossed.'],['Does a leap day count?','Yes. Calendar arithmetic includes February 29 in leap years.']],
'day-of-the-week-calculator':['Determine the weekday for a valid Gregorian calendar date and show its ISO weekday number. The date is validated before calculation, so impossible dates such as February 30 are rejected rather than normalized into March.','2024-02-29 was a Thursday, ISO weekday 4.',['Does it support dates before 1582?','It uses the proleptic Gregorian calendar; historical local calendars may differ.'],['What is ISO weekday numbering?','Monday is 1 and Sunday is 7.']]
};
