const chartFor = (slug, values, output) => {
  let points;
  if (slug === 'gpa-calculator') points = [1,2,3].map(i => ({label:`Course ${i} quality points`,value:Number(values[`grade${i}`])*Number(values[`credits${i}`])}));
  else if (slug === 'grade-calculator') points = [{label:'Current average',value:output.value},{label:'Target grade',value:Number(values.target)}];
  else if (slug === 'concrete-calculator') points = [{label:'Net concrete',value:output.details.find(x=>x.label==='Net volume').value},{label:'Order volume',value:output.value}];
  else if (slug === 'gdp-calculator') points = ['consumption','investment','government','exports','imports'].map(key=>({label:key[0].toUpperCase()+key.slice(1),value:Number(values[key])}));
  else if (slug === 'roofing-calculator') points = [{label:'Sloped roof area',value:output.details[0].value},{label:'Area with allowance',value:output.value}];
  else if (slug === 'tile-calculator') points = [{label:'Net tile count',value:output.details[1].value},{label:'Purchase tile count',value:output.value}];
  else if (slug === 'tip-calculator') points = [{label:'Bill before tip',value:Number(values.bill)},{label:'Tip',value:output.details[0].value},{label:'Total',value:output.details[1].value}];
  else if (slug === 'bandwidth-calculator') points = [{label:'Transfer seconds',value:output.value},{label:'Transfer minutes',value:output.value/60}];
  else if (slug === 'sleep-calculator') points = [{label:'Sleep-cycle minutes',value:Number(values.cycles)*90},{label:'Sleep latency minutes',value:Number(values.latency)}];
  if (!points?.length || points.some(p=>!Number.isFinite(p.value)||p.value<0)) return undefined;
  return points;
};
export const calculators = defs.map(([slug,title,fields])=>{let [description,example,faq1,faq2]=basicInfo[slug]??[];if(!description)throw new Error(`Missing editorial content for ${slug}`);const formula=({ 'age-calculator':'completed years = year difference adjusted for whether the anniversary has occurred','date-calculator':'result date = start date + signed calendar days','gpa-calculator':'GPA = Σ(grade points × credits) ÷ Σ credits','grade-calculator':'weighted average = Σ(score × weight) ÷ Σ entered weights','concrete-calculator':'volume = length × width × thickness × (1 + allowance)','ip-subnet-calculator':'network = IPv4 address AND CIDR mask','voltage-drop-calculator':'Vdrop = 2 × one-way length × current × resistivity ÷ conductor area','fuel-cost-calculator':'cost = distance × consumption per distance × price per fuel unit','gdp-calculator':'GDP = consumption + investment + government + exports − imports','horsepower-calculator':'hp = torque(lb-ft) × rpm ÷ 5252','engine-horsepower-calculator':'hp = torque(lb-ft) × rpm ÷ 5252','ohms-law-calculator':'V = I × R; P = V × I','molarity-calculator':'M = moles of solute ÷ final solution volume in liters','density-calculator':'density = mass ÷ volume','mass-calculator':'mass = density × volume','weight-calculator':'weight force = mass × gravitational acceleration','speed-calculator':'average speed = distance ÷ elapsed time','wind-chill-calculator':'WC = 35.74 + 0.6215T − 35.75V^0.16 + 0.4275T V^0.16','heat-index-calculator':'Rothfusz regression with NWS humidity adjustments','dew-point-calculator':'Magnus approximation: dew point = bγ ÷ (a − γ)','roofing-calculator':'roof area = footprint × √(1 + (rise/run)²)','tile-calculator':'tile count = ceiling(area ÷ tile area × (1 + allowance))','mulch-calculator':'cubic yards = area × depth(in) ÷ 12 ÷ 27','gravel-calculator':'volume = area × depth; estimated mass = volume × bulk density','tire-size-calculator':'diameter = 2 × width × aspect ratio + rim diameter','bandwidth-calculator':'seconds = file bits ÷ effective bits per second','time-duration-calculator':'elapsed minutes = end − start, adding one day when crossing midnight','day-counter-calculator':'calendar day difference = |end date − start date| ÷ 86,400,000','golf-handicap-calculator':'Handicap Index = rounded average of the lowest selected differentials plus the WHS adjustment for a 3, 4, or 6-score record' })[slug] ?? `${title} is calculated from the supplied measurement fields using the units shown.`;return {slug,title,category:'everyday',description,fields,calculate:values=>{for(const field of fields){if(field.type==='select'){const value=values?.[field.key];if(value===undefined||value===null||!field.options?.some(option=>String(option.value)===String(value)))throw new Error(`${field.key} must be one of the listed options.`);}if(field.type==='number'&&field.required!==false&&(values?.[field.key]===undefined||values?.[field.key]===null||String(values[field.key]).trim()===''))throw new Error(`${field.key} is required.`);}const output=calc(slug,values);const chart=chartFor(slug,values,output);if(chart)output.chart=chart;return output;},formula,explanation:`${description} ${example} The calculation validates each input and keeps its stated units explicit. ${faq1[1]} This is an estimate for the stated assumptions; confirm measurements and any applicable professional or local standards before relying on it.`,example,faqs:[{q:faq1[0],a:faq1[1]},{q:faq2[0],a:faq2[1]}],...(slug==='wind-chill-calculator'||slug==='heat-index-calculator'?{sources:[{label:'US National Weather Service',url:slug==='wind-chill-calculator'?'https://www.weather.gov/safety/cold-wind-chill-chart':'https://www.weather.gov/tbw/heatindex'}]}:slug==='golf-handicap-calculator'?{sources:[{label:'USGA Rules of Handicapping, Rule 5.2a',url:'https://www.usga.org/handicapping/roh/Content/rules/5%202a%20For%20Fewer%20Than%2020%20Scores.htm'}]}:{})};});
